+  --accent-400: oklch(86% 0.13 70);
+
+  --text-900: oklch(18% 0.02 255);
+  --text-700: oklch(35% 0.02 255);
+  --text-600: oklch(45% 0.02 255);
+  --muted-500: oklch(55% 0.02 255);
+  --border-200: oklch(90% 0.01 255);
+
+  --bg-50: oklch(99% 0.01 255);
+  --bg-100: oklch(97% 0.01 255);
+  --surface: oklch(100% 0 0);
+
+  --radius-lg: 18px;
+  --radius-md: 14px;
+  --radius-sm: 12px;
+
+  --shadow-sm: 0 1px 2px rgba(0,0,0,.06);
+  --shadow-md: 0 10px 30px rgba(2,8,23,.10);
+  --shadow-lg: 0 22px 70px rgba(2,8,23,.14);
+
+  --container: 1160px;
+  --gutter: 18px;
+
+  --focus: oklch(72% 0.14 255);
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";
+  color:var(--text-900);
+  background: radial-gradient(1200px 800px at 20% -10%, color-mix(in oklch, var(--brand-500), white 75%), transparent 60%),
+              radial-gradient(1000px 700px at 100% 0%, color-mix(in oklch, var(--accent-500), white 76%), transparent 55%),
+              var(--bg-50);
+  line-height:1.45;
+}
+
+a{color:inherit; text-decoration:none}
+a:hover{text-decoration:underline}
+
+img{max-width:100%; display:block}
+
+.container{
+  width:min(var(--container), 100% - (var(--gutter) * 2));
+  margin-inline:auto;
+}
+
+.topbar{
+  position:sticky;
+  top:0;
+  z-index:40;
+  background: color-mix(in oklch, var(--surface), var(--brand-950) 6%);
+  backdrop-filter: blur(12px);
+  border-bottom: 1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 10%);
+}
+
+.topbar-inner{display:flex; align-items:center; justify-content:space-between; gap:16px; padding:12px 0}
+
+.brand{
+  display:flex; align-items:center; gap:12px;
+  font-weight:800;
+  letter-spacing:-0.02em;
+}
+
+.logo{
+  width:38px; height:38px; border-radius:12px;
+  background: linear-gradient(135deg, var(--brand-500), var(--brand-800));
+  box-shadow: var(--shadow-sm);
+  position:relative;
+}
+
+.logo::after{
+  content:"";
+  position:absolute; inset:9px 10px 10px 9px;
+  border-radius:10px;
+  background: linear-gradient(135deg, color-mix(in oklch, var(--accent-500), white 20%), color-mix(in oklch, var(--accent-600), var(--brand-800) 35%));
+  opacity:.92;
+}
+
+.brand small{display:block; font-weight:600; color:var(--text-700); letter-spacing:0}
+
+.nav{
+  display:flex; gap:8px; align-items:center;
+}
+
+.nav a{
+  display:inline-flex; align-items:center; gap:8px;
+  padding:10px 12px;
+  border-radius:999px;
+  font-weight:650;
+  color:var(--text-700);
+  border:1px solid transparent;
+}
+
+.nav a[aria-current="page"], .nav a.active{
+  background: color-mix(in oklch, var(--brand-500), white 84%);
+  color:var(--brand-950);
+  border-color: color-mix(in oklch, var(--brand-500), white 70%);
+}
+
+.nav a:hover{
+  text-decoration:none;
+  background: color-mix(in oklch, var(--brand-500), white 90%);
+}
+
+.header-actions{display:flex; gap:10px; align-items:center}
+
+.pill{
+  border:1px solid var(--border-200);
+  background: color-mix(in oklch, var(--surface), var(--brand-950) 2%);
+  padding:8px 10px;
+  border-radius:999px;
+  font-weight:650;
+  color:var(--text-700);
+}
+
+.btn{
+  display:inline-flex; align-items:center; justify-content:center; gap:8px;
+  padding:12px 14px;
+  border-radius:12px;
+  border:1px solid transparent;
+  font-weight:750;
+  cursor:pointer;
+  transition: transform .12s ease, box-shadow .12s ease, background .12s ease, border-color .12s ease;
+}
+
+.btn:active{transform: translateY(1px)}
+
+.btn-primary{
+  background: linear-gradient(135deg, var(--accent-500), var(--accent-600));
+  color: oklch(18% 0.02 70);
+  box-shadow: 0 12px 24px rgba(255,183,0,.22);
+}
+
+.btn-primary:hover{box-shadow: 0 16px 30px rgba(255,183,0,.26)}
+
+.btn-secondary{
+  background: color-mix(in oklch, var(--brand-500), white 88%);
+  border-color: color-mix(in oklch, var(--brand-500), white 72%);
+  color: var(--brand-950);
+}
+
+.btn-ghost{
+  background: transparent;
+  border-color: color-mix(in oklch, var(--border-200), var(--brand-500) 18%);
+  color: var(--text-700);
+}
+
+.btn-ghost:hover{
+  background: color-mix(in oklch, var(--brand-500), white 92%);
+  border-color: color-mix(in oklch, var(--brand-500), white 78%);
+}
+
+.hero{
+  padding: 36px 0 18px;
+}
+
+.hero-grid{
+  display:grid;
+  grid-template-columns: 1.2fr .8fr;
+  gap: 22px;
+  align-items: stretch;
+}
+
+.hero-card{
+  background: color-mix(in oklch, var(--surface), var(--brand-950) 1%);
+  border: 1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 15%);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-lg);
+  overflow:hidden;
+}
+
+.hero-main{
+  padding: 22px;
+}
+
+.kicker{
+  display:inline-flex;
+  gap:8px;
+  align-items:center;
+  padding: 6px 10px;
+  border-radius: 999px;
+  background: color-mix(in oklch, var(--brand-500), white 90%);
+  color: var(--brand-950);
+  font-weight:750;
+  font-size: 12px;
+}
+
+.hero h1{margin:12px 0 6px; font-size: clamp(28px, 3.4vw, 44px); letter-spacing:-0.03em; line-height:1.1}
+.hero p{margin:0; color:var(--text-600); font-size: 15.5px}
+
+.search{
+  margin-top: 16px;
+  display:grid;
+  grid-template-columns: 1.2fr 1fr 1fr auto;
+  gap: 10px;
+}
+
+.field{
+  display:flex; flex-direction:column; gap:6px;
+}
+
+.label{font-weight:750; font-size:12px; color:var(--text-700)}
+
+input, select{
+  width:100%;
+  padding: 12px 12px;
+  border-radius: 12px;
+  border: 1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 12%);
+  background: var(--surface);
+  color: var(--text-900);
+  box-shadow: var(--shadow-sm);
+}
+
+input:focus, select:focus, button:focus{
+  outline: 3px solid color-mix(in oklch, var(--focus), white 40%);
+  outline-offset: 2px;
+}
+
+.inline-options{
+  display:flex; flex-wrap:wrap; gap:12px;
+  margin-top: 10px;
+}
+
+.checkbox{
+  display:inline-flex; gap:8px; align-items:center;
+  padding: 8px 10px;
+  border-radius: 12px;
+  border:1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 12%);
+  background: color-mix(in oklch, var(--surface), var(--brand-950) 1%);
+  color: var(--text-700);
+  font-weight:650;
+}
+
+.hero-side{
+  display:flex; flex-direction:column;
+}
+
+.side-media{
+  background:
+    radial-gradient(600px 400px at 30% 0%, color-mix(in oklch, var(--brand-500), white 78%), transparent 65%),
+    linear-gradient(135deg, var(--brand-900), var(--brand-950));
+  padding: 18px;
+  height:100%;
+  position:relative;
+}
+
+.side-media .glow{
+  position:absolute; inset:-40px -40px auto auto;
+  width: 220px; height: 220px; border-radius: 50%;
+  filter: blur(40px);
+  background: color-mix(in oklch, var(--accent-500), white 20%);
+  opacity:.55;
+}
+
+.side-media .card{
+  position:relative;
+  border-radius: 16px;
+  border: 1px solid rgba(255,255,255,.14);
+  background: rgba(255,255,255,.06);
+  padding: 16px;
+  color: rgba(255,255,255,.92);
+  box-shadow: 0 20px 60px rgba(0,0,0,.25);
+}
+
+.side-media h3{margin:0 0 6px; font-size: 16px; letter-spacing:-0.01em}
+.side-media p{margin:0 0 12px; color: rgba(255,255,255,.80); font-size: 13.5px}
+
+.badge-row{display:grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap:10px; margin-top: 12px}
+.mini-badge{
+  border-radius: 14px;
+  background: rgba(255,255,255,.06);
+  border: 1px solid rgba(255,255,255,.12);
+  padding: 10px;
+}
+.mini-badge strong{display:block; font-size: 13px}
+.mini-badge span{display:block; font-size: 12px; opacity:.82}
+
+.section{padding: 24px 0}
+
+.section-head{
+  display:flex; align-items:end; justify-content:space-between; gap:12px;
+  margin-bottom: 14px;
+}
+
+.section h2{margin:0; font-size: 22px; letter-spacing:-0.02em}
+.section p.lead{margin:6px 0 0; color: var(--text-600); max-width: 70ch}
+
+.grid-3{display:grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px}
+.grid-4{display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px}
+.grid-2{display:grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px}
+
+.card{
+  background: var(--surface);
+  border: 1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 12%);
+  border-radius: var(--radius-md);
+  box-shadow: var(--shadow-md);
+  overflow:hidden;
+}
+
+.card-body{padding: 14px}
+.card-title{font-weight: 820; letter-spacing:-0.02em}
+.muted{color: var(--text-600)}
+
+.trust{
+  display:flex; gap:12px; align-items:flex-start;
+  padding: 14px;
+}
+
+.icon{
+  width: 40px; height: 40px;
+  border-radius: 14px;
+  background: color-mix(in oklch, var(--brand-500), white 88%);
+  border: 1px solid color-mix(in oklch, var(--brand-500), white 70%);
+  display:grid; place-items:center;
+  color: var(--brand-900);
+}
+
+.trust strong{display:block; margin-bottom: 4px; letter-spacing:-0.01em}
+.trust span{display:block; color: var(--text-600); font-size: 13.5px}
+
+.chips{display:flex; flex-wrap:wrap; gap:10px}
+.chip{
+  padding: 10px 12px;
+  border-radius: 999px;
+  border: 1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 12%);
+  background: color-mix(in oklch, var(--surface), var(--brand-950) 1%);
+  font-weight: 700;
+  color: var(--text-700);
+}
+
+.tabs{
+  display:flex;
+  gap: 8px;
+  flex-wrap:wrap;
+  padding: 6px;
+  border-radius: 999px;
+  background: color-mix(in oklch, var(--brand-500), white 92%);
+  border: 1px solid color-mix(in oklch, var(--brand-500), white 80%);
+}
+
+.tab{
+  border: 1px solid transparent;
+  background: transparent;
+  padding: 10px 12px;
+  border-radius: 999px;
+  font-weight: 760;
+  color: var(--text-700);
+  cursor:pointer;
+}
+
+.tab[aria-selected="true"]{
+  background: var(--surface);
+  border-color: color-mix(in oklch, var(--brand-500), white 70%);
+  color: var(--brand-950);
+  box-shadow: var(--shadow-sm);
+}
+
+.tab:hover{background: color-mix(in oklch, var(--surface), var(--brand-950) 2%)}
+
+.tabpanels{margin-top: 12px}
+
+.carousel{
+  position:relative;
+}
+
+.carousel-track{
+  display:flex;
+  gap: 12px;
+  overflow:auto;
+  scroll-snap-type:x mandatory;
+  scroll-behavior:smooth;
+  padding: 2px;
+}
+
+.carousel-track::-webkit-scrollbar{height:10px}
+.carousel-track::-webkit-scrollbar-thumb{background: color-mix(in oklch, var(--brand-500), white 70%); border-radius:999px}
+.carousel-track::-webkit-scrollbar-track{background: transparent}
+
+.carousel-item{
+  flex: 0 0 320px;
+  scroll-snap-align: start;
+}
+
+.carousel-nav{
+  position:absolute;
+  inset: 0;
+  pointer-events:none;
+}
+
+.carousel-btn{
+  pointer-events:auto;
+  position:absolute;
+  top: 44%;
+  transform: translateY(-50%);
+  width: 44px; height: 44px;
+  border-radius: 14px;
+  border: 1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 18%);
+  background: color-mix(in oklch, var(--surface), var(--brand-950) 2%);
+  box-shadow: var(--shadow-md);
+  cursor:pointer;
+}
+
+.carousel-btn:hover{background: color-mix(in oklch, var(--brand-500), white 92%)}
+.carousel-btn.left{left: -10px}
+.carousel-btn.right{right: -10px}
+
+.media{
+  aspect-ratio: 16/10;
+  background: linear-gradient(135deg, color-mix(in oklch, var(--brand-500), white 70%), color-mix(in oklch, var(--brand-900), white 10%));
+  border-bottom: 1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 12%);
+}
+
+.media img{width:100%; height:100%; object-fit:cover}
+
+.price{display:flex; gap:10px; align-items:baseline; justify-content:space-between}
+.price strong{font-size: 18px; letter-spacing:-0.01em}
+.strike{text-decoration: line-through; color: var(--muted-500); font-weight: 650}
+
+.meta{display:flex; gap:10px; flex-wrap:wrap; color: var(--text-600); font-weight: 650; font-size: 13px}
+.rating{
+  display:inline-flex; align-items:center; gap:8px;
+  padding: 6px 10px;
+  border-radius: 999px;
+  background: color-mix(in oklch, var(--brand-500), white 90%);
+  color: var(--brand-950);
+  font-weight: 800;
+}
+
+.callout{
+  background: linear-gradient(135deg, color-mix(in oklch, var(--brand-500), white 90%), var(--surface));
+  border: 1px solid color-mix(in oklch, var(--brand-500), white 75%);
+  border-radius: var(--radius-lg);
+  padding: 18px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 14px;
+}
+
+.callout h3{margin:0 0 6px; letter-spacing:-0.02em}
+.callout p{margin:0; color: var(--text-600)}
+
+.footer{
+  margin-top: 20px;
+  padding: 26px 0 36px;
+  border-top: 1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 12%);
+  background: color-mix(in oklch, var(--surface), var(--brand-950) 1%);
+}
+
+.footer-grid{display:grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 16px}
+.footer h4{margin:0 0 10px}
+.footer a{display:block; color: var(--text-700); padding: 6px 0; font-weight: 650}
+.footer a:hover{text-decoration: underline}
+
+.small{font-size: 12.5px; color: var(--text-600)}
+
+.alert{
+  margin-top: 12px;
+  border: 1px solid color-mix(in oklch, var(--accent-500), white 65%);
+  background: color-mix(in oklch, var(--accent-400), white 70%);
+  color: oklch(22% 0.02 70);
+  border-radius: 14px;
+  padding: 10px 12px;
+  display:none;
+}
+
+.alert.show{display:block}
+
+.accordion{display:grid; gap:10px}
+.acc-item{
+  border:1px solid color-mix(in oklch, var(--border-200), var(--brand-500) 12%);
+  background: var(--surface);
+  border-radius: var(--radius-md);
+  box-shadow: var(--shadow-sm);
+  overflow:hidden;
+}
+.acc-btn{
+  width:100%;
+  text-align:left;
+  padding: 14px;
+  border:0;
+  background: transparent;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:12px;
+  cursor:pointer;
+  font-weight: 780;
+}
+.acc-btn span{color: var(--text-700)}
+.acc-panel{padding: 0 14px 14px; color: var(--text-600); display:none}
+.acc-item[data-open="true"] .acc-panel{display:block}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns: 1fr}
+  .search{grid-template-columns: 1fr 1fr;}
+  .grid-4{grid-template-columns: repeat(2, minmax(0, 1fr))}
+  .grid-3{grid-template-columns: repeat(2, minmax(0, 1fr))}
+  .footer-grid{grid-template-columns: 1fr 1fr}
+  .carousel-btn.left{left: 6px}
+  .carousel-btn.right{right: 6px}
+}
+
+@media (max-width: 620px){
+  .topbar-inner{flex-wrap:wrap}
+  .nav{width:100%; overflow:auto; padding-bottom: 4px}
+  .search{grid-template-columns: 1fr}
+  .grid-2,.grid-3,.grid-4{grid-template-columns: 1fr}
+  .badge-row{grid-template-columns: 1fr}
+  .carousel-item{flex-basis: 86vw}
+}
+
*** End Patch
PATCH

