page_to_file={p['page_id']:p['file'] for p in spec['pages']}

checks=[]
for it in spec['interactions']:
    file=page_to_file[it['page']]
    text=htmls[file]
    if it['id']=='home-trip-planner-tabs':
        checks.append(('home trip tabs', 'data-tabs' in text and 'Trip planner categories' in text))
    if it['id']=='home-unique-properties-carousel':
        checks.append(('home carousel', 'data-carousel' in text and 'data-carousel-prev' in text and 'data-carousel-next' in text))
    if it['id']=='home-popular-tabs':
        checks.append(('home popular tabs', 'Popular links categories' in text and 'Domestic cities' in text))
    if it['id']=='home-search-form':
        checks.append(('home search', 'data-home-search' in text and 'data-search-alert' in text))
    if it['id']=='packages-package-type-radio':
        checks.append(('packages radio', 'data-package-form' in text and 'name="package_type"' in text and 'data-package-hint' in text))
    if it['id']=='car-rental-faq-accordion':
        checks.append(('car faq', 'data-accordion' in text and 'data-acc-item' in text and 'data-acc-btn' in text))
    if it['id']=='car-rental-destination-tabs':
        checks.append(('car dest tabs', 'Car rental destination categories' in text and 'role="tab"' in text))
    if it['id']=='attractions-region-tabs':
        checks.append(('attr region tabs', 'aria-label="Regions"' in text and 'rg-1' in text))
    if it['id']=='attractions-things-to-do-tabs':
        checks.append(('attr things tabs', 'aria-label="Activity categories"' in text and 'ac-1' in text))

bad=[c for c in checks if not c[1]]
print('checks',len(checks),'bad',len(bad))
for name,_ in bad:
    print('FAIL',name)
